package com.sobrenaturaldirector;
import static org.junit.Assert.*;import java.util.*;import org.junit.Test;import net.minecraft.nbt.NBTTagCompound;import com.sobrenaturaldirector.narrative.*;import com.sobrenaturaldirector.persistence.DirectorWorldSavedData;
public class NarrativeThreadManagerTest{
 @Test public void threadIsIdempotentAndPersists(){DirectorWorldSavedData d=new DirectorWorldSavedData();NarrativeThreadManager m=new NarrativeThreadManager();PersistentNarrativeThread a=m.create(d,"thread-a","missing-signal",0,1,2,Collections.singleton("signal"),10,"CREATED_FROM_MEANINGFUL_EVIDENCE");assertSame(a,m.create(d,"thread-a","different",0,1,2,Collections.<String>emptySet(),11,null));NBTTagCompound n=new NBTTagCompound();d.writeToNBT(n);DirectorWorldSavedData loaded=new DirectorWorldSavedData();loaded.readFromNBT(n);assertEquals("missing-signal",loaded.getNarrativeThread("thread-a").getSubject());}
 @Test public void terminalThreadDoesNotResume(){DirectorWorldSavedData d=new DirectorWorldSavedData();NarrativeThreadManager m=new NarrativeThreadManager();m.create(d,"thread-b","signal",0,0,0,Collections.<String>emptySet(),1,"CREATED");m.resolve(d,"thread-b",2,"RESOLVED");try{m.resume(d,"thread-b",3,"RETURNED");fail();}catch(IllegalStateException expected){}}
 @Test public void arbitrationContextIsExplicitAndImmutable(){DirectorWorldSavedData d=new DirectorWorldSavedData();NarrativeThreadManager m=new NarrativeThreadManager();m.create(d,"thread-context","signal",0,0,0,Collections.singleton("continuity"),1,"CREATED");NarrativeThreadArbitrationContext c=m.arbitrationContext(d,"thread-context");assertEquals("thread-context",c.getThreadId());assertEquals(NarrativeThreadState.ACTIVE,c.getState());assertTrue(c.getTags().contains("continuity"));}
 @Test public void boundedEvaluationIsDeterministic(){DirectorWorldSavedData d=new DirectorWorldSavedData();NarrativeThreadManager m=new NarrativeThreadManager();for(int i=0;i<10;i++)m.create(d,"thread-"+i,"signal-"+i,0,0,0,Collections.<String>emptySet(),i,"CREATED");final List<String> seen=new ArrayList<String>();assertEquals(8,m.evaluateBounded(d,new NarrativeThreadManager.ThreadAssessment(){public void assess(PersistentNarrativeThread t,long tick){seen.add(t.getId());}},20));assertEquals("thread-0",seen.get(0));assertEquals("thread-7",seen.get(7));}
}
